#!/usr/bin/env node
// OMP Documenter self-contained installer. Writes only to a new destination.
// No network requests, subprocesses, package installation or OMP configuration changes.
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import crypto from "node:crypto";

const distribution = {"name":"omp-documenter","version":"2.0.0","files":[{"path":".gitignore","mode":420,"sha256":"147f739f03a238478aa7bae96b8e07d3be3a5c5313333af5911819c1f97471d2","base64":"bm9kZV9tb2R1bGVzLwouZG9jdW1lbnRlci8KY292ZXJhZ2UvCioubG9nCg=="},{"path":"CHANGELOG.md","mode":420,"sha256":"5ea7aba818e6265adeef2015aafe1f736ed1d9f7cb941cac931f56697c031a70","base64":""},{"path":"docs/ARCHITECTURE.md","mode":420,"sha256":"bfd79b65df0e0c148fe2b81bdfd0b85b937382e772fb7ac96940d980042ea256","base64":""},{"path":"docs/DOCUMENTATION-GUIDE.md","mode":420,"sha256":"d5f585c82d83547fe5c7f7e13d695ee4c58cfb53b65dfbcd1c39826e7c5af317","base64":""},{"path":"docs/DOCUMENTATION-SET.md","mode":420,"sha256":"013ce6f22fddc72db69f152111bc12df07a6d003b5cf5e694c6ca0c1f9db9e3c","base64":""},{"path":"docs/ENGINE.md","mode":420,"sha256":"ea7594379c60acb3737dd61acd5c279ffdeeda7a63ddf2c4e784765d24b54b65","base64":""},{"path":"docs/MIGRATION-2.0.md","mode":420,"sha256":"dd4bb2bd40e22fb5bf965dcb0ef5f2e37d625509c0efe75182d4e8b8bdfdfa99","base64":""},{"path":"docs/RELEASE-CHECKLIST.md","mode":420,"sha256":"a4823f657dc531606b85b5ef3b92137fa19dee12446b4a18990d08e529cee6b5","base64":""},{"path":"docs/ROADMAP.md","mode":420,"sha256":"8ac85c2ebb612e5a1650206bea0db01f9233775bc004c9fae183d27aa721c7a1","base64":""},{"path":"docs/USER-GUIDE.md","mode":420,"sha256":"eddf3ed3eefab4be4168368513e49c71d454a0bfac5d9666d87b3181da0e394a","base64":""},{"path":"docs/VALIDATION.md","mode":420,"sha256":"6312915be8b0c150408d362592367730e115d9f8db7408cee16295671245671f","base64":""},{"path":"lib/engine.mjs","mode":420,"sha256":"803d4b24391a7ae14772f7d8bc0a7ae769227d006629a246bede7dfb43390886","base64":""},{"path":"lib/style.mjs","mode":420,"sha256":"93b0b79c3fb893c7f46f8f2332e1e228f7061e38077b64cfe67595a42e98f9fa","base64":""},{"path":"lib/symbols.mjs","mode":420,"sha256":"68d6e622d475006e045c1e9ce28be5faa33c08e5d7a4c4b92423394443c0fcd9","base64":""},{"path":"lib/verification.mjs","mode":420,"sha256":"7b379738382cc1b6f989e025c9b6dae3817bb96cca067b1e975d20fa7bec9fb8","base64":""},{"path":"package.json","mode":420,"sha256":"017266c141ab8e393fc0ab8537999a5908a05fd33c53f60e4c1560a2b82cd4fc","base64":""},{"path":"README.md","mode":420,"sha256":"e54559a2861d4185db4de5c5821c2ebb8701266c3b9e2b35a6380b44cb066546","base64":""},{"path":"scripts/benchmark.mjs","mode":493,"sha256":"1e68f8875a537c8a7395b5efc69581e27afb3feff17de707ad64ca28dd133b5c","base64":""},{"path":"scripts/build-distribution.mjs","mode":493,"sha256":"31ec173e62d3409af382694af810256eec7065571721a07184bca1ed5e58ab6f","base64":""},{"path":"scripts/documenter.mjs","mode":493,"sha256":"b0eb49c23cd2e2aecd5dccb9466278e401cf0f9f43c148a78400bf0f00a91a69","base64":""},{"path":"scripts/generate-guide.mjs","mode":493,"sha256":"b4894e9986829bac650c1469dc780007a6a98d2a66aa8e78176561845d5b8832","base64":""},{"path":"scripts/release-evidence.mjs","mode":493,"sha256":"97edd3d74f2c31637f8e336b6532583fb3574e8659c8dc68839ff3dee15f86db","base64":""},{"path":"scripts/renderer-check.mjs","mode":493,"sha256":"886788818904e8b9ad6c603efccec268188352d3538a4f10c74547b0fa9b9316","base64":""},{"path":"scripts/verify-examples.mjs","mode":493,"sha256":"b9a9bfc276088c3b3983a7b5709c1a4be708bdfeac5126acbe33e47be8b6cb69","base64":""},{"path":"skills/omp-documenter/references/coverage.md","mode":420,"sha256":"8ca5cb946521d30c8edf7da6864b5f392e6dbf4b7768b604a1b764bc1a62bcb5","base64":""},{"path":"skills/omp-documenter/references/evidence.md","mode":420,"sha256":"bd69120c6cf7f64e7d65af96c86e2acc1ef4dd598dc3bc7d37279c6def9062f6","base64":""},{"path":"skills/omp-documenter/references/maintenance.md","mode":420,"sha256":"72b33e35b0dd9baf5b35acdcd3035f5b6a8607ceff52795e4ec26a633fcdeb92","base64":""},{"path":"skills/omp-documenter/references/operations.md","mode":420,"sha256":"d01eec97e65774330b2865018779ee143aa9adebbed17c2e7096be3fa7fe1409","base64":""},{"path":"skills/omp-documenter/references/parallel.md","mode":420,"sha256":"89ae8583af3dbf8182fbfd282ed10159daae8257869edb531ae6ee62bb914ad2","base64":""},{"path":"skills/omp-documenter/references/workflow.md","mode":420,"sha256":"6b29217f658f96a0438cb6767f69b5459f3f9e4a9de098edd27c3871bfafb962","base64":""},{"path":"skills/omp-documenter/references/writing-standard.md","mode":420,"sha256":"52ede41de890aa06a351db0c3401806538e9fcc7f930bd8d66e927b10fda395a","base64":""},{"path":"skills/omp-documenter/SKILL.md","mode":420,"sha256":"a4d68deeed52250b0d39bc962d8655a6ac6bce73b2b9578854ac90a2b963000f","base64":""},{"path":"src/index.js","mode":420,"sha256":"be8b5b2fe3ece49e7d274709adba749b8d7988536ebe7896be3d1b01d238e399","base64":""},{"path":"templates/chapter.md","mode":420,"sha256":"d82e8415bd099e15e0dadc9e1cd61b4f420e8ef1f176e66f8d1f99e3273daecb","base64":""},{"path":"templates/unknowns.md","mode":420,"sha256":"db018dc8fe572a36a4cf02195da6a5c2289c5f4ff6f75d563ba178e5f19fe67a","base64":""},{"path":"tests/cli.test.mjs","mode":420,"sha256":"55337b5c67e08ab78528b436fe76749d09af5cc44c970da6be4996b0dfb5d2df","base64":""},{"path":"tests/distribution.test.mjs","mode":420,"sha256":"72dbcd7ae1766ed6b98daea92a5b77796c51e989b4ba2c5a4c43a7dd6779da67","base64":""},{"path":"tests/engine.test.mjs","mode":420,"sha256":"a5c6aa6cd498d9b7cfca2f8beea1d8afbcb91f90f46edcb2248af322ef0c7264","base64":""},{"path":"tests/extension.test.mjs","mode":420,"sha256":"cb0d127d742ce42058da0d494a851df813b25b22bccc16341946abb5f0ee244d","base64":""},{"path":"tests/style.test.mjs","mode":420,"sha256":"4527c12ccd9ea747773e44b98aa62cf5ebba62b7775516e2bfad3697377c6f97","base64":""},{"path":"tests/symbols.test.mjs","mode":420,"sha256":"7feabd33d91ba8900fb2197dc30b8124a3e51e2ca58dc77cdbad8fcb4920cb9e","base64":""},{"path":"tests/v2.test.mjs","mode":420,"sha256":"9b3a88a9d7ad3ee3c03eeffe3cd202c53ef435100017dca7431eb14e283baf98","base64":""},{"path":"tests/verification.test.mjs","mode":420,"sha256":"b367b7c955a2c8601a031dbb8d27b649fb609e6b4654bdd853de1cd18cae3854","base64":""}]};
const hash = value => crypto.createHash("sha256").update(value).digest("hex");

function ensureSafeParents(destination) {
  const parsed = path.parse(destination);
  let current = parsed.root;
  for (const part of path.relative(parsed.root, destination).split(path.sep)) {
    if (!part) continue;
    current = path.join(current, part);
    let stat;
    try { stat = fs.lstatSync(current); }
    catch (error) {
      if (error.code !== "ENOENT") throw error;
      fs.mkdirSync(current, { mode: 0o700 });
      stat = fs.lstatSync(current);
    }
    if (stat.isSymbolicLink() || !stat.isDirectory()) throw new Error("Destination parent must be a normal directory: " + current);
  }
}

try {
  const args = process.argv.slice(2);
  if (args.length === 1 && ["--help", "-h"].includes(args[0])) {
    process.stdout.write("Usage: node omp-documenter-" + distribution.version + "-install.mjs [new-destination-directory]\nWrites the full plugin into a new directory. No OMP settings are changed.\n");
  } else {
    if (args.length > 1) throw new Error("Expected at most one destination directory. Use --help.");
    const destination = path.resolve(args[0] || path.join(os.homedir(), ".local", "share", "omp-documenter-" + distribution.version));
    let exists = false;
    try { fs.lstatSync(destination); exists = true; } catch (error) { if (error.code !== "ENOENT") throw error; }
    if (exists) throw new Error("Destination already exists; no files were changed. Choose a new directory: " + destination);
    const seen = new Set();
    for (const file of distribution.files) {
      if (!file.path || file.path.startsWith("/") || file.path.includes("\\") || /^[A-Za-z]:/.test(file.path) || file.path.split("/").some(part => !part || part === "." || part === "..") || seen.has(file.path)) throw new Error("Invalid packaged path.");
      seen.add(file.path);
      if (hash(Buffer.from(file.base64, "base64")) !== file.sha256) throw new Error("Package content check failed: " + file.path);
    }
    ensureSafeParents(path.dirname(destination));
    fs.mkdirSync(destination, { mode: 0o700 });
    for (const file of distribution.files) {
      const absolute = path.join(destination, ...file.path.split("/"));
      ensureSafeParents(path.dirname(absolute));
      fs.writeFileSync(absolute, Buffer.from(file.base64, "base64"), { flag: "wx", mode: file.mode });
      if (hash(fs.readFileSync(absolute)) !== file.sha256) throw new Error("Installed content check failed: " + file.path);
    }
    process.stdout.write("Installed OMP Documenter " + distribution.version + " (" + distribution.files.length + " files) in:\n" + destination + "\n\nNext: run omp plugin link with this directory as its argument, then start OMP in your project and run /documenter initial.\n");
  }
} catch (error) {
  process.stderr.write("Documenter installer: " + error.message + "\n");
  process.exitCode = 1;
}
